{"args":{"content":"package main\n\nimport (\n\t\"net/http\"\n\t\"net/http/httptest\"\n\t\"testing\"\n\t\"time\"\n)\n\n// TestSessionLookupTable exercises the /session GET handler's status codes\n// through a fresh mux, in the same table-driven style as the expiry table.\nfunc TestSessionLookupTable(t *testing.T) {\n\tdefer func() { timeNow = time.Now }()\n\n\tbase := time.Date(2024, 1, 1, 12, 0, 0, 0, time.UTC)\n\tsid := \"live-session\"\n\tsessions[sid] = \u0026Session{ExpiresAt: base.Add(10 * time.Minute)}\n\n\ttests := []struct {\n\t\tname       string\n\t\tmethod     string\n\t\tid         string\n\t\tat         time.Time\n\t\twantStatus int\n\t}{\n\t\t{name: \"live session\", method: http.MethodGet, id: sid, at: base, wantStatus: http.StatusOK},\n\t\t{name: \"missing session\", method: http.MethodGet, id: \"nope\", at: base, wantStatus: http.StatusNotFound},\n\t\t{name: \"wrong method\", method: http.MethodPost, id: sid, at: base, wantStatus: http.StatusMethodNotAllowed},\n\t}\n\n\tfor _, tc := range tests {\n\t\ttc := tc\n\t\tt.Run(tc.name, func(t *testing.T) {\n\t\t\ttimeNow = func() time.Time { return tc.at }\n\n\t\t\tmux := http.NewServeMux()\n\t\t\tmux.HandleFunc(\"/session\", handleSession)\n\n\t\t\treq := httptest.NewRequest(tc.method, \"/session?id=\"+tc.id, nil)\n\t\t\trec := httptest.NewRecorder()\n\t\t\tmux.ServeHTTP(rec, req)\n\n\t\t\tif rec.Code != tc.wantStatus {\n\t\t\t\tt.Errorf(\"status = %d, want %d\", rec.Code, tc.wantStatus)\n\t\t\t}\n\t\t})\n\t}\n}\n","path":"lookup_table_test.go"},"id":"call_write_file_9404e7e9c7152133","name":"write_file","runId":"run_20260911171155_4cd12d","schemaVersion":2,"sideEffect":"write","type":"tool_call"}
